mapper.select:
select t.id, t.item_id, t.limit_purchase_id, t.max_discount_amount, t.start_time, t.advance_time, t.end_time, t.min_price, t.sku_value from limit_purchase_item t left join limit_purchase r on t.limit_purchase_id = r.id where t.item_id = #{itemId} and t.deleted = false and r.state = 1 and now() between t.start_time and t.end_time
and t.merchant_id = #{merchantId}
limit 1

select count(t.id) from limit_purchase_item t left join limit_purchase r on t.limit_purchase_id = r.id
where t.deleted = false and r.state = 1 and now() < t.end_time and t.merchant_id = #{merchantId}

    and t.limit_purchase_id <> #{limitId}

and t.item_id in

    #{item}
